function checkLeadField(name:string,value:string){const v=value.trim();
  if(name==='did')return v?'':'Choose the DID / transfer line the call came in on.';
  if(name==='customer')return v?'':'Enter the customer’s name.';
  if(name==='phone'){if(!v)return 'Enter the customer’s phone number.';return /^(1)?\d{10}$/.test(v.replace(/\D/g,''))?'':'Enter a 10-digit US phone number, like 202-555-0143.';}
  if(name==='age')return !v||(/^\d{1,3}$/.test(v)&&Number(v)<=120)?'':'Enter an age between 0 and 120, or leave it blank.';
  if(name==='zip')return !v||/^\d{5}$/.test(v)?'':'A ZIP code has 5 digits, like 75001.';
  if(name==='state')return !v||/^[A-Z]{2}$/.test(v)?'':'Use the 2-letter state code, like TX.';
  return '';}
