{tab==='Overview'&&<><div className="conversion-strip"><div><span>Call → transfer</span><strong>{pct(metrics.callToTransfer)}</strong><small>{metrics.transfers} transfers / {metrics.calls} calls</small></div><div><span>Transfer → sale</span><strong>{pct(metrics.transferToSale)}</strong><small>{metrics.sales} sales / {metrics.transfers} transfers</small></div><div><span>Current LPD</span><strong>{decimal(metrics.lpd)}</strong><small>{metrics.leads} leads / {metrics.days} working days</small></div><div><span>Confirmed sales</span><strong>{metrics.sales}</strong><small>Manually confirmed by administrator</small></div></div><details className="metric-help"><summary>How these numbers are calculated</summary><p>LPD = leads submitted ÷ recorded working days. Working days include call-activity entries and lead-submission dates across all campaigns and DIDs in the selected period. Percentages use recorded call and transfer totals.</p></details><div className="stats">{[[Phone,'Calls taken',taken,'Dialer activity recorded'],[ArrowUpRight,'Calls transferred',transfers,taken?`${(transfers/taken*100).toFixed(1)}% transfer rate`:'Add call activity to begin'],[CheckCircle2,'CPA approved',cpa,'Confirmed acquisitions'],[CheckCircle2,'CPL approved',cpl,'Qualified leads approved']].map(([Icon,label,value,note]:any,i)=><div className={'stat '+(i===2?'featured':'')} key={label}><div>{label}<Icon size={18}/></div><strong>{value.toLocaleString()}</strong><small>{note}</small><div className="stat-line"/></div>)}</div><div className="overview-grid"><section className="panel"><div className="panel-head"><div><h2>Campaign performance</h2><p>A clear view of what’s converting.</p></div><span className="pill">{campaign==='All campaigns'?CAMPAIGNS.length:1} campaigns</span></div><div className="table-scroll"><table><thead><tr><th>CAMPAIGN</th><th>CALLS</th><th>TRANSFERS</th><th>CPA</th><th>CPL</th></tr></thead><tbody>{campaignRows.shown.map(c=>{const i=CAMPAIGNS.indexOf(c);const cl=ls.filter((r:any)=>r.campaign===c),cc=cs.filter((r:any)=>r.campaign===c);return <tr key={c}><td><span className={'campaign-icon c'+i}>{c.slice(0,2).toUpperCase()}</span><b>{c}</b></td><td>{cc.reduce((n:number,r:any)=>n+r.taken,0)}</td><td>{cc.reduce((n:number,r:any)=>n+r.transferred,0)}</td><td><span className="number-pill">{cl.filter((r:any)=>r.status==='cpa').length}</span></td><td>{cl.filter((r:any)=>r.status==='cpl').length}</td></tr>})}</tbody></table></div>{campaignRows.hidden>0&&<div className="show-more show-more--inline"><span>{campaignRows.hidden} {campaignRows.hidden===1?'campaign has':'campaigns have'} no activity in this view.</span><button type="button" className="text-btn" onClick={()=>setShowAllCampaigns(true)}>Show all campaigns</button></div>}{showAllCampaigns&&campaignRows.active<campaignRows.total&&<div className="show-more show-more--inline"><span>Showing all {campaignRows.total} campaigns.</span><button type="button" className="text-btn" onClick={()=>setShowAllCampaigns(false)}>Show only active</button></div>}<div className="panel-foot"><span><Clock size={14}/> {pending} leads awaiting a decision</span><button className="text-btn" onClick={()=>{setStatus('pending');setTab('Lead pipeline');}}>Review pipeline <ArrowRight size={14}/></button></div></section><section className="panel pace"><div className="panel-head"><div><h2>Approval snapshot</h2><p>Submitted leads, final outcomes.</p></div><Activity size={18}/></div><div className="approval-ring" style={{'--pct':`${ls.length?(cpa+cpl)/ls.length*100:0}%`} as any}><div><strong>{ls.length?Math.round((cpa+cpl)/ls.length*100):0}%</strong><small>approval rate</small></div></div><div className="legend"><span><i className="dot green"/> Approved <b>{cpa+cpl}</b></span><span><i className="dot amber"/> Pending <b>{pending}</b></span><span><i className="dot grey"/> Rejected <b>{ls.filter((r:any)=>outcomeOf(r)==='not_sale').length}</b></span></div></section></div><div className="section-heading"><div><h2>People making an impact</h2><p>Ranked by confirmed sales, then CPA + CPL approvals.</p></div><button className="text-btn" onClick={()=>setTab('Leaderboard')}>Full leaderboard <ArrowRight size={15}/></button></div>{renderRanks(rank.slice(0,3))}<section className="panel recent-panel"><div className="panel-head"><div><h2>Recent submissions</h2><p>Your latest activity, without the noise.</p></div><button className="text-btn" onClick={()=>setTab('Lead pipeline')}>View all <ArrowRight size={15}/></button></div>{leadTable(rows.slice(0,5))}</section></>}
